use clap::{Parser, ValueEnum};
use std::path::{Path, PathBuf};
use walkdir::WalkDir;
use regex::Regex;
use std::fs;
use std::io::Write;

#[derive(Debug, Clone, ValueEnum)]
enum FileType {
    #[value(name = "f")]
    File,
    #[value(name = "d")]
    Dir,
    #[value(name = "l")]
    Symlink,
    #[value(name = "x")]
    Executable,
    #[value(name = "e")]
    Empty,
    #[value(name = "s")]
    Socket,
    #[value(name = "p")]
    Pipe,
}

#[derive(Debug, Clone, ValueEnum)]
enum ColorWhen {
    #[value(name = "auto")]
    Auto,
    #[value(name = "always")]
    Always,
    #[value(name = "never")]
    Never,
}

#[derive(Parser, Debug)]
#[command(name = "fd")]
#[command(version = "10.3.0")]
#[command(about = "A program to find entries in your filesystem")]
#[command(long_about = None)]
struct Args {
    /// The search pattern
    pattern: Option<String>,

    /// The directory where the filesystem search is rooted
    #[arg(value_name = "path")]
    path: Vec<PathBuf>,

    /// Include hidden files and directories
    #[arg(short = 'H', long)]
    hidden: bool,

    /// Show ignored files
    #[arg(short = 'I', long)]
    no_ignore: bool,

    /// Case-sensitive search
    #[arg(short = 's', long)]
    case_sensitive: bool,

    /// Case-insensitive search
    #[arg(short = 'i', long)]
    ignore_case: bool,

    /// Use glob pattern instead of regex
    #[arg(short = 'g', long)]
    glob: bool,

    /// Treat pattern as literal string
    #[arg(short = 'F', long)]
    fixed_strings: bool,

    /// Show absolute paths
    #[arg(short = 'a', long)]
    absolute_path: bool,

    /// Use detailed listing format like ls -l
    #[arg(short = 'l', long)]
    list_details: bool,

    /// Follow symbolic links
    #[arg(short = 'L', long)]
    follow: bool,

    /// Match against full path
    #[arg(short = 'p', long)]
    full_path: bool,

    /// Print null separator instead of newlines
    #[arg(short = '0', long)]
    print0: bool,

    /// Maximum search depth
    #[arg(short = 'd', long)]
    max_depth: Option<usize>,

    /// Filter by file type
    #[arg(short = 't', long)]
    file_type: Option<FileType>,

    /// Filter by extension
    #[arg(short = 'e', long)]
    extension: Option<String>,

    /// Exclude patterns
    #[arg(short = 'E', long)]
    exclude: Vec<String>,

    /// Color when
    #[arg(short = 'c', long, value_name = "when")]
    color: Option<ColorWhen>,

    /// Number of threads
    #[arg(short = 'j', long)]
    threads: Option<usize>,

    /// Limit number of results
    #[arg(long)]
    max_results: Option<usize>,

    /// Limit to single result
    #[arg(short = '1')]
    limit_one: bool,

    /// Quiet mode
    #[arg(short = 'q', long)]
    quiet: bool,

    /// Execute command for each result
    #[arg(short = 'x', long, value_name = "cmd")]
    exec: Option<String>,

    /// Execute command for batch
    #[arg(short = 'X', long, value_name = "cmd")]
    exec_batch: Option<String>,
}

fn main() {
    let args = Args::parse();

    let pattern = args.pattern.unwrap_or_else(|| ".".to_string());
    let search_paths = if args.path.is_empty() {
        vec![PathBuf::from(".")]
    } else {
        args.path
    };

    let max_depth = if args.limit_one { Some(1) } else { args.max_results.or(args.max_depth) };

    let mut found_count = 0;
    let max_results = if args.limit_one { 1 } else { args.max_results.unwrap_or(usize::MAX) };

    for search_path in search_paths {
        let walker = WalkDir::new(&search_path)
            .into_iter()
            .filter_map(|e| e.ok());

        for entry in walker {
            if found_count >= max_results {
                break;
            }

            let metadata = match entry.metadata() {
                Ok(m) => m,
                Err(_) => continue,
            };

            let path = entry.path();
            let file_name = path.file_name().unwrap_or_default().to_string_lossy();

            // Skip hidden files unless requested
            if !args.hidden && file_name.starts_with('.') && path != search_path {
                if metadata.is_dir() {
                    continue;
                }
            }

            // Check depth
            let depth = path.components().count() - search_path.components().count();
            if let Some(max_d) = args.max_depth {
                if depth > max_d {
                    if metadata.is_dir() {
                        continue;
                    }
                }
            }

            // Check file type
            if let Some(ref ft) = args.file_type {
                let matches = match ft {
                    FileType::File => metadata.is_file(),
                    FileType::Dir => metadata.is_dir(),
                    FileType::Symlink => metadata.is_symlink(),
                    FileType::Executable => metadata.is_file() && is_executable(&metadata),
                    FileType::Empty => {
                        if metadata.is_dir() {
                            is_dir_empty(path)
                        } else {
                            metadata.len() == 0
                        }
                    },
                    FileType::Socket => is_socket(&metadata),
                    FileType::Pipe => is_pipe(&metadata),
                };
                if !matches {
                    continue;
                }
            }

            // Check pattern match
            let match_against = if args.full_path {
                path.to_string_lossy().to_string()
            } else {
                file_name.to_string()
            };

            let matches = if args.fixed_strings {
                match_against.contains(&pattern)
            } else if args.glob {
                glob_match(&pattern, &match_against)
            } else {
                regex_match(&pattern, &match_against, !args.case_sensitive && !args.ignore_case, args.case_sensitive)
            };

            if !matches {
                continue;
            }

            // Check extension
            if let Some(ref ext) = args.extension {
                let file_ext = path.extension().unwrap_or_default().to_string_lossy();
                if file_ext != ext {
                    continue;
                }
            }

            if !args.quiet {
                let output_path = if args.absolute_path {
                    path.canonicalize().unwrap_or_else(|_| path.to_path_buf()).to_string_lossy().to_string()
                } else {
                    path.to_string_lossy().to_string()
                };

                if args.print0 {
                    print!("{}\0", output_path);
                } else {
                    println!("{}", output_path);
                }
            }

            found_count += 1;
        }

        if found_count >= max_results {
            break;
        }
    }

    let exit_code = if args.quiet {
        if found_count > 0 { 0 } else { 1 }
    } else {
        0
    };

    std::process::exit(exit_code);
}

fn regex_match(pattern: &str, text: &str, case_insensitive: bool, _case_sensitive: bool) -> bool {
    let regex_str = if case_insensitive {
        format!("(?i){}", pattern)
    } else {
        pattern.to_string()
    };

    match Regex::new(&regex_str) {
        Ok(re) => re.is_match(text),
        Err(_) => false,
    }
}

fn glob_match(pattern: &str, text: &str) -> bool {
    // Simple glob matching - convert to regex
    let regex_pattern = globset::GlobBuilder::new(pattern)
        .build()
        .ok()
        .and_then(|g| globset::RegexSet::new(vec![g.regex()])
            .ok()
            .map(|rs| rs))
        .is_some();
    regex_pattern
}

fn is_executable(metadata: &fs::Metadata) -> bool {
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        let mode = metadata.permissions().mode();
        mode & 0o111 != 0
    }
    #[cfg(not(unix))]
    {
        false
    }
}

fn is_dir_empty(path: &Path) -> bool {
    fs::read_dir(path).map(|mut rd| rd.next().is_none()).unwrap_or(false)
}

fn is_socket(_metadata: &fs::Metadata) -> bool {
    #[cfg(unix)]
    {
        use std::os::unix::fs::FileTypeExt;
        _metadata.file_type().is_socket()
    }
    #[cfg(not(unix))]
    {
        false
    }
}

fn is_pipe(_metadata: &fs::Metadata) -> bool {
    #[cfg(unix)]
    {
        use std::os::unix::fs::FileTypeExt;
        _metadata.file_type().is_fifo()
    }
    #[cfg(not(unix))]
    {
        false
    }
}
