    limit_one: bool,

    /// Quiet mode
    #[arg(short = 'q', long)]
    quiet: bool,

    /// Execute command for each result
    #[arg(short = 'x', long, value_name = "cmd")]
    exec: Option<String>,

    /// Execute command for batch
    #[arg(short = 'X', long, value_name = "cmd")]
    exec_batch: Option<String>,
}

fn main() {
