use std::fs;
use std::path::Path;
use crate::args::FileType;

pub struct DirEntry {
    pub path: std::path::PathBuf,
    pub depth: usize,
}

pub struct Matcher {
    pattern: String,
    case_sensitive: bool,
    ignore_case: bool,
    glob: bool,
    fixed_strings: bool,
    full_path: bool,
    extension: Option<String>,
    file_type: Option<FileType>,
}

impl Matcher {
    pub fn new(
        pattern: &str,
        case_sensitive: bool,
        ignore_case: bool,
        glob: bool,
        fixed_strings: bool,
        full_path: bool,
        extension: &Option<String>,
        file_type: &Option<FileType>,
    ) -> Self {
        Matcher {
            pattern: pattern.to_string(),
            case_sensitive,
            ignore_case,
            glob,
            fixed_strings,
            full_path,
            extension: extension.clone(),
            file_type: file_type.clone(),
        }
    }

    pub fn matches(&self, entry: &DirEntry) -> bool {
        // Check file type
        if let Some(ref ft) = self.file_type {
            if !self.matches_file_type(&entry.path, ft) {
                return false;
            }
        }

        // Check extension
        if let Some(ref ext) = self.extension {
            if let Some(file_ext) = entry.path.extension() {
                if file_ext.to_string_lossy().as_ref() != ext {
                    return false;
                }
            } else {
                return false;
            }
        }

        // Check pattern
        let match_against = if self.full_path {
            entry.path.to_string_lossy().to_string()
        } else {
            entry.path.file_name()
                .map(|n| n.to_string_lossy().to_string())
                .unwrap_or_default()
        };

        if self.fixed_strings {
            self.match_fixed_string(&match_against)
        } else if self.glob {
            self.match_glob(&match_against)
        } else {
            self.match_regex(&match_against)
        }
    }

    fn matches_file_type(&self, path: &Path, file_type: &FileType) -> bool {
        let metadata = match fs::symlink_metadata(path) {
            Ok(m) => m,
            Err(_) => return false,
        };

        match file_type {
            FileType::File => metadata.is_file(),
            FileType::Dir => metadata.is_dir(),
            FileType::Symlink => metadata.is_symlink(),
            FileType::Executable => {
                metadata.is_file() && self.is_executable(&metadata)
            },
            FileType::Empty => {
                if metadata.is_dir() {
                    self.is_dir_empty(path)
                } else {
                    metadata.len() == 0
                }
            },
            FileType::Socket => self.is_socket(&metadata),
            FileType::Pipe => self.is_pipe(&metadata),
        }
    }

    fn match_fixed_string(&self, text: &str) -> bool {
        if self.ignore_case || (!self.case_sensitive && !text.chars().any(|c| c.is_uppercase())) {
            text.to_lowercase().contains(&self.pattern.to_lowercase())
        } else {
            text.contains(&self.pattern)
        }
    }

    fn match_glob(&self, text: &str) -> bool {
        glob_match(&self.pattern, text, self.case_sensitive || self.ignore_case)
    }

    fn match_regex(&self, text: &str) -> bool {
        regex_match(&self.pattern, text, self.case_sensitive || self.ignore_case)
    }

    fn is_executable(&self, metadata: &fs::Metadata) -> bool {
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            let mode = metadata.permissions().mode();
            mode & 0o111 != 0
        }
        #[cfg(not(unix))]
        {
            false
        }
    }

    fn is_dir_empty(&self, path: &Path) -> bool {
        fs::read_dir(path).map(|mut rd| rd.next().is_none()).unwrap_or(false)
    }

    fn is_socket(&self, _metadata: &fs::Metadata) -> bool {
        #[cfg(unix)]
        {
            use std::os::unix::fs::FileTypeExt;
            _metadata.file_type().is_socket()
        }
        #[cfg(not(unix))]
        {
            false
        }
    }

    fn is_pipe(&self, _metadata: &fs::Metadata) -> bool {
        #[cfg(unix)]
        {
            use std::os::unix::fs::FileTypeExt;
            _metadata.file_type().is_fifo()
        }
        #[cfg(not(unix))]
        {
            false
        }
    }
}

fn glob_match(pattern: &str, text: &str, _ignore_case: bool) -> bool {
    simple_glob_match(pattern, text)
}

fn regex_match(pattern: &str, text: &str, smart_case: bool) -> bool {
    if pattern == "." || pattern == "^" {
        return true;
    }

    // Simple regex matching for common cases
    if smart_case {
        text.to_lowercase().contains(&pattern.to_lowercase())
    } else {
        text.contains(pattern)
    }
}

fn simple_glob_match(pattern: &str, text: &str) -> bool {
    // Very basic glob matching
    if pattern.is_empty() {
        return text.is_empty();
    }

    if pattern == "*" {
        return true;
    }

    if pattern.contains('*') {
        let parts: Vec<&str> = pattern.split('*').collect();
        if parts.len() == 2 {
            let start = parts[0];
            let end = parts[1];
            return text.starts_with(start) && text.ends_with(end);
        }
    }

    text.contains(pattern)
}
