use std::fs;
use std::path::Path;
use std::collections::VecDeque;
use crate::matcher::DirEntry;

pub struct DirWalker {
    max_depth: Option<usize>,
    hidden: bool,
    no_ignore: bool,
    follow: bool,
}

impl DirWalker {
    pub fn new(
        max_depth: Option<usize>,
        hidden: bool,
        no_ignore: bool,
        follow: bool,
    ) -> Self {
        DirWalker {
            max_depth,
            hidden,
            no_ignore,
            follow,
        }
    }

    pub fn walk(&self, root: &Path) -> Vec<DirEntry> {
        let mut entries = Vec::new();
        let mut queue = VecDeque::new();

        if let Ok(metadata) = fs::metadata(root) {
            if metadata.is_dir() {
                queue.push_back((root.to_path_buf(), 0));
            } else {
                entries.push(DirEntry {
                    path: root.to_path_buf(),
                    depth: 0,
                });
            }
        }

        while let Some((dir, depth)) = queue.pop_front() {
            // Check if we should descend into this directory
            if let Some(max_d) = self.max_depth {
                if depth > max_d {
                    continue;
                }
            }

            if let Ok(read_dir) = fs::read_dir(&dir) {
                for entry_result in read_dir {
                    if let Ok(entry) = entry_result {
                        let path = entry.path();
                        let file_name = path.file_name()
                            .map(|n| n.to_string_lossy())
                            .unwrap_or_default();

                        // Skip hidden files unless requested
                        if !self.hidden && file_name.starts_with('.') {
                            continue;
                        }

                        let metadata = match fs::symlink_metadata(&path) {
                            Ok(m) => m,
                            Err(_) => continue,
                        };

                        let entry_depth = depth + 1;

                        // Add this entry to results if within depth limit
                        if self.max_depth.is_none() || entry_depth <= self.max_depth.unwrap() {
                            entries.push(DirEntry { 
                                path: path.clone(),
                                depth: entry_depth,
                            });
                        }

                        // Queue directory for traversal if we haven't exceeded depth
                        if metadata.is_dir() {
                            if !self.follow && metadata.is_symlink() {
                                continue;
                            }
                            if self.max_depth.is_none() || entry_depth <= self.max_depth.unwrap() {
                                queue.push_back((path, entry_depth));
                            }
                        }
                    }
                }
            }
        }

        // Sort entries for consistent output
        entries.sort_by(|a, b| a.path.cmp(&b.path));
        entries
    }
}
