use std::path::PathBuf;

#[derive(Debug, Clone)]
pub enum FileType {
    File,
    Dir,
    Symlink,
    Executable,
    Empty,
    Socket,
    Pipe,
}

#[derive(Debug, Clone)]
pub struct Args {
    pub pattern: Option<String>,
    pub paths: Vec<PathBuf>,
    pub hidden: bool,
    pub no_ignore: bool,
    pub case_sensitive: bool,
    pub ignore_case: bool,
    pub glob: bool,
    pub fixed_strings: bool,
    pub absolute_path: bool,
    pub list_details: bool,
    pub follow: bool,
    pub full_path: bool,
    pub print0: bool,
    pub max_depth: Option<usize>,
    pub file_type: Option<FileType>,
    pub extension: Option<String>,
    pub exclude: Vec<String>,
    pub color: Option<String>,
    pub threads: Option<usize>,
    pub max_results: Option<usize>,
    pub limit_one: bool,
    pub quiet: bool,
    pub exec: Option<String>,
    pub exec_batch: Option<String>,
    pub show_version: bool,
    pub show_help: bool,
}

impl Args {
    pub fn parse(args: Vec<String>) -> Self {
        let mut result = Args {
            pattern: None,
            paths: Vec::new(),
            hidden: false,
            no_ignore: false,
            case_sensitive: false,
            ignore_case: false,
            glob: false,
            fixed_strings: false,
            absolute_path: false,
            list_details: false,
            follow: false,
            full_path: false,
            print0: false,
            max_depth: None,
            file_type: None,
            extension: None,
            exclude: Vec::new(),
            color: None,
            threads: None,
            max_results: None,
            limit_one: false,
            quiet: false,
            exec: None,
            exec_batch: None,
            show_version: false,
            show_help: false,
        };

        let mut i = 1;
        let mut positional_args = Vec::new();

        while i < args.len() {
            let arg = &args[i];

            match arg.as_str() {
                "-h" | "--help" => {
                    result.show_help = true;
                    return result;
                },
                "-V" | "--version" => {
                    result.show_version = true;
                    return result;
                },
                "-H" | "--hidden" => result.hidden = true,
                "-I" | "--no-ignore" => result.no_ignore = true,
                "-u" | "--unrestricted" => {
                    result.hidden = true;
                    result.no_ignore = true;
                },
                "-s" | "--case-sensitive" => result.case_sensitive = true,
                "-i" | "--ignore-case" => result.ignore_case = true,
                "-g" | "--glob" => result.glob = true,
                "-F" | "--fixed-strings" => result.fixed_strings = true,
                "-a" | "--absolute-path" => result.absolute_path = true,
                "-l" | "--list-details" => result.list_details = true,
                "-L" | "--follow" => result.follow = true,
                "-p" | "--full-path" => result.full_path = true,
                "-0" | "--print0" => result.print0 = true,
                "-1" => result.limit_one = true,
                "-q" | "--quiet" => result.quiet = true,
                "-d" | "--max-depth" => {
                    i += 1;
                    if i < args.len() {
                        if let Ok(depth) = args[i].parse() {
                            result.max_depth = Some(depth);
                        }
                    }
                },
                "-t" | "--type" => {
                    i += 1;
                    if i < args.len() {
                        result.file_type = parse_file_type(&args[i]);
                    }
                },
                "-e" | "--extension" => {
                    i += 1;
                    if i < args.len() {
                        result.extension = Some(args[i].clone());
                    }
                },
                "-E" | "--exclude" => {
                    i += 1;
                    if i < args.len() {
                        result.exclude.push(args[i].clone());
                    }
                },
                "-c" | "--color" => {
                    i += 1;
                    if i < args.len() {
                        result.color = Some(args[i].clone());
                    }
                },
                "-j" | "--threads" => {
                    i += 1;
                    if i < args.len() {
                        if let Ok(threads) = args[i].parse() {
                            result.threads = Some(threads);
                        }
                    }
                },
                "--max-results" => {
                    i += 1;
                    if i < args.len() {
                        if let Ok(count) = args[i].parse() {
                            result.max_results = Some(count);
                        }
                    }
                },
                "-x" | "--exec" => {
                    i += 1;
                    if i < args.len() {
                        result.exec = Some(args[i].clone());
                    }
                },
                "-X" | "--exec-batch" => {
                    i += 1;
                    if i < args.len() {
                        result.exec_batch = Some(args[i].clone());
                    }
                },
                arg if arg.starts_with('-') => {
                    // Unknown option - ignore
                },
                _ => positional_args.push(arg.clone()),
            }

            i += 1;
        }

        // Process positional arguments
        for arg in positional_args {
            if result.pattern.is_none() {
                result.pattern = Some(arg);
            } else {
                result.paths.push(PathBuf::from(arg));
            }
        }

        result
    }
}

fn parse_file_type(s: &str) -> Option<FileType> {
    match s {
        "f" => Some(FileType::File),
        "d" => Some(FileType::Dir),
        "l" => Some(FileType::Symlink),
        "x" => Some(FileType::Executable),
        "e" => Some(FileType::Empty),
        "s" => Some(FileType::Socket),
        "p" => Some(FileType::Pipe),
        _ => None,
    }
}
