        let metadata = match fs::symlink_metadata(path) {
            Ok(m) => m,
            Err(_) => return false,
        };

        match file_type {
            FileType::File => metadata.is_file(),
            FileType::Dir => metadata.is_dir(),
            FileType::Symlink => metadata.is_symlink(),
            FileType::Executable => {
                metadata.is_file() && self.is_executable(&metadata)
            },
            FileType::Empty => {
