        fs::read_dir(path).map(|mut rd| rd.next().is_none()).unwrap_or(false)
    }

    fn is_socket(&self, _metadata: &fs::Metadata) -> bool {
        #[cfg(unix)]
        {
            use std::os::unix::fs::FileTypeExt;
            _metadata.file_type().is_socket()
        }
        #[cfg(not(unix))]
        {
            false
        }
    }

    fn is_pipe(&self, _metadata: &fs::Metadata) -> bool {
        #[cfg(unix)]
        {
            use std::os::unix::fs::FileTypeExt;
            _metadata.file_type().is_fifo()
        }
        #[cfg(not(unix))]
        {
            false
        }
    }
}

fn glob_match(pattern: &str, text: &str) -> bool {
    simple_glob_match(pattern, text)
}

fn regex_match(pattern: &str, text: &str, case_sensitive: bool, ignore_case: bool) -> bool {
    if pattern == "." || pattern == "^" || pattern.is_empty() {
        return true;
    }

    // Simple regex matching for common cases
    // For a full regex engine, we would need an external crate, but we'll do basic patterns
    if ignore_case {
        text.to_lowercase().contains(&pattern.to_lowercase())
    } else if case_sensitive {
        text.contains(pattern)
    } else {
        // Smart case - if pattern contains uppercase, do case-sensitive search
        if pattern.chars().any(|c| c.is_uppercase()) {
            text.contains(pattern)
        } else {
            text.to_lowercase().contains(&pattern.to_lowercase())
        }
    }
}

fn simple_glob_match(pattern: &str, text: &str) -> bool {
    // Very basic glob matching
    if pattern.is_empty() {
        return text.is_empty();
    }

    if pattern == "*" {
        return true;
    }

    // Handle ** (recursive wildcard)
    if pattern == "**" {
        return true;
    }

    // Handle patterns like "*.rs"
    if pattern.starts_with('*') && !pattern[1..].contains('*') {
        let suffix = &pattern[1..];
        return text.ends_with(suffix);
    }

    // Handle patterns like "main.*"
    if pattern.ends_with('*') && !pattern[..pattern.len()-1].contains('*') {
        let prefix = &pattern[..pattern.len()-1];
        return text.starts_with(prefix);
    }

    // Handle patterns like "*.rs" or "test_*.py" with * in middle
    if pattern.contains('*') {
        let parts: Vec<&str> = pattern.split('*').collect();
        if parts.len() == 2 {
            let start = parts[0];
            let end = parts[1];
            if start.is_empty() {
                return text.ends_with(end);
            } else if end.is_empty() {
                return text.starts_with(start);
            } else {
                return text.starts_with(start) && text.ends_with(end);
            }
        }
    }

    text.contains(pattern)
}
