use std::fs;
use crate::matcher::DirEntry;

pub struct OutputFormatter {
    absolute_path: bool,
    print0: bool,
}

impl OutputFormatter {
    pub fn new(absolute_path: bool, print0: bool) -> Self {
        OutputFormatter {
            absolute_path,
            print0,
        }
    }

    pub fn print(&self, entry: &DirEntry) {
        let metadata = fs::symlink_metadata(&entry.path);
        let is_dir = metadata.map(|m| m.is_dir()).unwrap_or(false);

        let output_path = if self.absolute_path {
            entry.path.canonicalize()
                .unwrap_or_else(|_| entry.path.clone())
                .to_string_lossy()
                .to_string()
        } else {
            // Convert path to string, removing leading "./"
            let path_str = entry.path.to_string_lossy().to_string();
            if path_str.starts_with("./") {
                path_str[2..].to_string()
            } else if path_str == "." {
                String::new()
            } else {
                path_str
            }
        };

        let final_path = if is_dir && !output_path.is_empty() && !output_path.ends_with('/') {
            format!("{}/", output_path)
        } else {
            output_path
        };

        if self.print0 {
            print!("{}\0", final_path);
        } else {
            if !final_path.is_empty() {
                println!("{}", final_path);
            }
        }
    }
}
EOF

